    /// Render the preview tab
    pub(super) fn render_preview_tab(&self, _cx: &mut Context<Self>) -> impl IntoElement {
        div().size_full().child(self.showcase.clone())
    }

    /// Render the export tab
    pub(super) fn render_export_tab(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = &self.theme;
        let export_format = self.export_format.clone();

        let export_content = if export_format == "json" {
            self.theme
                .to_json()
                .unwrap_or_else(|e| format!("Error: {}", e))
        } else {
            self.theme.to_rust_code()
        };

        div().p_6().size_full().child(
            VStack::new()
                .spacing(StackSpacing::Lg)
                // Theme name display
                .child(
                    HStack::new()
                        .spacing(StackSpacing::Md)
                        .child(
                            Text::new("Theme Name:")
                                .size(TextSize::Md)
                                .weight(TextWeight::Bold)
                                .color(theme.text_primary.to_rgba()),
                        )
                        .child(
                            Text::new(SharedString::from(self.theme.name.clone()))
                                .size(TextSize::Md)
                                .color(theme.text_primary.to_rgba()),
                        )
                        .build(),
                )
                // Format selection
                .child(
                    HStack::new()
                        .spacing(StackSpacing::Md)
                        .child(
                            Text::new("Export Format:")
                                .size(TextSize::Md)
                                .color(theme.text_primary.to_rgba()),
                        )
                        .child(
                            Button::new("format-json", "JSON")
                                .variant(if export_format == "json" {
                                    ButtonVariant::Primary
                                } else {
                                    ButtonVariant::Secondary
                                })
                                .size(ButtonSize::Sm)
                                .build()
                                .on_click(cx.listener(|this, _: &ClickEvent, _window, cx| {
                                    this.export_format = "json".to_string();
                                    cx.notify();
                                })),
                        )
                        .child(
                            Button::new("format-rust", "Rust")
                                .variant(if export_format == "rust" {
                                    ButtonVariant::Primary
                                } else {
                                    ButtonVariant::Secondary
                                })
                                .size(ButtonSize::Sm)
                                .build()
                                .on_click(cx.listener(|this, _: &ClickEvent, _window, cx| {
                                    this.export_format = "rust".to_string();
                                    cx.notify();
                                })),
                        )
                        .build(),
                )
                // Export preview
                .child(
                    div()
                        .flex_1()
                        .w_full()
                        .p_4()
                        .bg(theme.background_tertiary.to_rgba())
                        .rounded_lg()
                        .border_1()
                        .border_color(theme.border.to_rgba())
                        .child(
                            div()
                                .text_sm()
                                .text_color(theme.text_primary.to_rgba())
                                .child(export_content),
                        ),
                )
                // Action buttons
                .child(
                    HStack::new()
                        .spacing(StackSpacing::Md)
                        .child(
                            Button::new("copy-btn", "Copy to Clipboard")
                                .variant(ButtonVariant::Primary)
                                .size(ButtonSize::Md)
                                .build()
                                .on_click(cx.listener(|this, _: &ClickEvent, _window, cx| {
                                    let content = if this.export_format == "json" {
                                        this.theme.to_json().unwrap_or_default()
                                    } else {
                                        this.theme.to_rust_code()
                                    };
                                    cx.write_to_clipboard(gpui::ClipboardItem::new_string(content));
                                })),
                        )
                        .child(
                            Button::new("save-btn", "Save to File")
                                .variant(ButtonVariant::Secondary)
                                .size(ButtonSize::Md)
                                .build()
                                .on_click(cx.listener(|this, _: &ClickEvent, _window, _cx| {
                                    let content = if this.export_format == "json" {
                                        this.theme.to_json().unwrap_or_default()
                                    } else {
                                        this.theme.to_rust_code()
                                    };
                                    let filename = format!(
                                        "{}_theme.{}",
                                        this.theme.name.to_lowercase().replace(' ', "_"),
                                        this.export_format
                                    );
                                    if let Err(e) = std::fs::write(&filename, content) {
                                        eprintln!("Failed to save theme to {filename}: {e}");
                                    } else {
                                        println!("Theme saved to {filename}");
                                    }
                                })),
                        )
                        .build(),
                )
                .build(),
        )
    }

